`n-- Table pour les notifications Push`nCREATE TABLE IF NOT EXISTS public.push_subscriptions (`n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),`n    subscription JSONB NOT NULL,`n    user_agent TEXT,`n    created_at TIMESTAMPTZ DEFAULT now()`n);`n`n-- Politique de sécurité (Rercherche simplifiée pour l admin)`nALTER TABLE public.push_subscriptions ENABLE ROW LEVEL SECURITY;`nCREATE POLICY \"Admins can manage subscriptions\" ON public.push_subscriptions FOR ALL USING (true);
`n-- Différenciation des abonnés`nALTER TABLE public.push_subscriptions ADD COLUMN IF NOT EXISTS role TEXT DEFAULT 'customer';
`n-- Table pour le suivi de livraison en temps réel`nCREATE TABLE IF NOT EXISTS public.delivery_tracks (`n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),`n    chef_id UUID DEFAULT auth.uid(),`n    latitude FLOAT8 NOT NULL,`n    longitude FLOAT8 NOT NULL,`n    updated_at TIMESTAMPTZ DEFAULT now(),`n    is_active BOOLEAN DEFAULT true`n);`n`nALTER TABLE public.delivery_tracks ENABLE ROW LEVEL SECURITY;`nCREATE POLICY \"Public can read active tracks\" ON public.delivery_tracks FOR SELECT USING (is_active = true);`nCREATE POLICY \"Chef can manage own tracks\" ON public.delivery_tracks FOR ALL USING (true);
